using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses "Discriminator"
        // (capital D) by default instead of "$type". For existing documents that
        // already store "Discriminator", no change is needed — EF9 now matches.
        //
        // However, if you had previously overridden the discriminator property name
        // to something custom, or if your existing docs use "$type", you must
        // explicitly configure it:
        //
        // modelBuilder.Entity<Product>().HasDiscriminator<string>("$type");

        modelBuilder.Entity<Product>().ToContainer("Products");
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported by the
    // Cosmos DB provider. All queries must use async methods (ToListAsync,
    // FirstOrDefaultAsync, etc.) instead of sync methods (ToList, FirstOrDefault).
    async Task<List<Product>> GetProductsByCategoryAsync(CosmosDbContext db, string category)
    {
        // BEFORE (EF8 - sync, now throws InvalidOperationException in EF9):
        // return db.Products.Where(p => p.Category == category).ToList();

        // AFTER (EF9 - must use async):
        return await db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    async Task<Product?> GetProductAsync(CosmosDbContext db, string id)
    {
        // BEFORE (sync):
        // return db.Products.FirstOrDefault(p => p.Id == id);

        // AFTER (async):
        return await db.Products.FirstOrDefaultAsync(p => p.Id == id);
    }
}

